/* ==========================================
   Z-SCORE CON REFERENCIAS NOMINALES FIJAS
   AP, AN, BP, BN, CP, CN y CAUDAL

   Calibración: 25 mediciones nominales
   Umbral de anomalía: |Z| >= 3
   Las referencias no cambian en ejecución.
   ========================================== */

// ------------------------------------------
// 1. REFERENCIAS NOMINALES FIJAS
// ------------------------------------------

const REFERENCIA = {
    AP:     { media: 447.12,  desviacion: 115.0403 },
    AN:     { media: 621.44,  desviacion: 35.6149 },
    BP:     { media: 413.08,  desviacion: 31.7660 },
    BN:     { media: 558.92,  desviacion: 42.7697 },
    CP:     { media: 383.08,  desviacion: 48.2579 },
    CN:     { media: 583.96,  desviacion: 65.2109 },
    CAUDAL: { media: 3.3480,  desviacion: 0.7094 }
};

const VARIABLES = ["AP", "AN", "BP", "BN", "CP", "CN"];
const UMBRAL_Z = 3;

// ------------------------------------------
// 2. OBTENER EL CICLO ACTUAL
// ------------------------------------------

const ciclos = flow.get("ciclos") || [];

if (!Array.isArray(ciclos) || ciclos.length === 0) {
    node.warn("Z-Score: no hay ciclos disponibles.");
    return null;
}

const cicloActual = ciclos[ciclos.length - 1];

// ------------------------------------------
// 3. CALCULAR Z-SCORE DE LOS SEIS TIEMPOS
// ------------------------------------------

const tiempos = {};
const zscore = {};

for (const variable of VARIABLES) {
    const valorOriginal = cicloActual[variable];
    const actual = Number(valorOriginal);

    const media = REFERENCIA[variable].media;
    const desviacion = REFERENCIA[variable].desviacion;

    if (
        valorOriginal === null ||
        valorOriginal === undefined ||
        valorOriginal === "" ||
        !Number.isFinite(actual) ||
        desviacion <= 0
    ) {
        node.warn(
            "Z-Score: valor inválido para " + variable +
            " en el ciclo " + cicloActual.ciclo
        );
        return null;
    }

    const z = (actual - media) / desviacion;

    tiempos[variable] = actual;

    zscore[variable] = {
        actual: actual,
        media: media,
        desviacion: desviacion,
        zscore: Number(z.toFixed(4)),
        estado: Math.abs(z) >= UMBRAL_Z
            ? "ANOMALIA"
            : "NORMAL"
    };
}

// ------------------------------------------
// 4. CALCULAR Z-SCORE DEL CAUDAL
// ------------------------------------------

const valorOriginalCaudal = cicloActual.caudal;

const caudalActual =
    valorOriginalCaudal === null ||
    valorOriginalCaudal === undefined ||
    valorOriginalCaudal === ""
        ? NaN
        : Number(valorOriginalCaudal);

if (!Number.isFinite(caudalActual)) {
    node.warn(
        "Z-Score: caudal inválido en el ciclo " +
        cicloActual.ciclo
    );
    return null;
}

const mediaCaudal = REFERENCIA.CAUDAL.media;
const desviacionCaudal = REFERENCIA.CAUDAL.desviacion;

const zCaudal =
    (caudalActual - mediaCaudal) / desviacionCaudal;

zscore.caudal = {
    actual: caudalActual,
    media: mediaCaudal,
    desviacion: desviacionCaudal,
    zscore: Number(zCaudal.toFixed(4)),
    estado: Math.abs(zCaudal) >= UMBRAL_Z
        ? "ANOMALIA"
        : "NORMAL"
};

// ------------------------------------------
// 5. ENTREGAR RESULTADO
// ------------------------------------------

msg.payload = {
    ciclo: cicloActual.ciclo,
    tiempos: tiempos,
    zscore: zscore,
    referenciaFija: true,
    referenciaCaudal: {
        media: mediaCaudal,
        desviacion: desviacionCaudal,
        muestras: 25,
        estado: "Referencia nominal fija"
    }
};

// Guardar Z-Scores para el Dashboard
flow.set("ultimoZScoreDashboard", zscore);

// Estado visual del nodo
const variablesAnomalas = Object.keys(zscore).filter(
    variable =>
        Math.abs(zscore[variable].zscore) >= UMBRAL_Z
);

if (variablesAnomalas.length > 0) {
    node.status({
        fill: "red",
        shape: "dot",
        text: "Anomalía | ciclo " + cicloActual.ciclo
    });
} else {
    node.status({
        fill: "green",
        shape: "dot",
        text: "Ciclo normal | " + cicloActual.ciclo
    });
}

return msg;

let datos = msg.payload;

// ==========================================
// 1. LIMPIAR HISTORIAL CUANDO SE SOLICITE
// ==========================================
if (msg.limpiar === true) {
    flow.set("historialAnomalias", []);
    flow.set("contadorAnomalias", {
        AP: 0,
        AN: 0,
        BP: 0,
        BN: 0,
        CP: 0,
        CN: 0,
        caudal: 0
    });

    flow.set("estadoAnomaliaDashboard", {
        ciclo: null,
        estadoGeneral: "SIN DATOS",
        anomalia: false,
        falla: false,
        estados: {}
    });

    node.status({
        fill: "green",
        shape: "dot",
        text: "Historial limpiado"
    });

    msg.payload = [];
    return msg;
}

// ==========================================
// 2. VALIDAR DATOS RECIBIDOS
// ==========================================
if (!datos || typeof datos !== "object") {
    return null;
}

if (
    datos.ciclo === null ||
    datos.ciclo === undefined ||
    datos.ciclo === ""
) {
    node.warn("Detección: ciclo no válido.");
    return null;
}

// ==========================================
// 3. CONFIGURACIÓN
// ==========================================
const variables = [
    "AP", "AN", "BP", "BN", "CP", "CN", "caudal"
];

const UMBRAL = 3;
const LIMITE_FALLA = 3;
const MAX_HISTORIAL = 100;

const identificadorCiclo = String(datos.ciclo);

// ==========================================
// 4. EVITAR EVALUAR DOS VECES EL MISMO CICLO
// ==========================================
const ultimoCicloEvaluado =
    flow.get("ultimoCicloEvaluadoDeteccion");

if (ultimoCicloEvaluado === identificadorCiclo) {
    return null;
}

// ==========================================
// 5. RECUPERAR MEMORIA
// ==========================================
let contadores = flow.get("contadorAnomalias") || {};
let historial = flow.get("historialAnomalias") || [];

if (!Array.isArray(historial)) {
    historial = [];
}

for (const variable of variables) {
    if (
        typeof contadores[variable] !== "number" ||
        !Number.isFinite(contadores[variable])
    ) {
        contadores[variable] = 0;
    }
}

// ==========================================
// 6. EVALUAR VARIABLES
// ==========================================
let anomalia = false;
let falla = false;
let evaluadas = 0;
let texto = "";

let estados = {};

texto += "CICLO: " + datos.ciclo + "\n";
texto += "-------------------------\n";

for (const variable of variables) {
    const dato = datos.zscore
        ? datos.zscore[variable]
        : null;

    if (!dato || typeof dato !== "object") {
        estados[variable] = {
            actual: datos.tiempos
                ? datos.tiempos[variable] ?? null
                : null,
            zscore: null,
            estado: "SIN REFERENCIA",
            contador: contadores[variable]
        };

        texto += variable + ": SIN REFERENCIA\n";
        continue;
    }

    const actual = Number(dato.actual);

    const z =
        dato.zscore === null ||
        dato.zscore === undefined ||
        dato.zscore === ""
            ? NaN
            : Number(dato.zscore);

    if (!Number.isFinite(z)) {
        estados[variable] = {
            actual: Number.isFinite(actual) ? actual : null,
            zscore: null,
            estado: "SIN REFERENCIA",
            contador: contadores[variable]
        };

        texto += variable + ": SIN REFERENCIA\n";
        continue;
    }

    evaluadas++;

    const esAnomalia = Math.abs(z) >= UMBRAL;
    let estado;

    if (esAnomalia) {
        contadores[variable]++;
        anomalia = true;

        // Evitar duplicar una variable en el mismo ciclo.
        const yaRegistrada = historial.some(item =>
            String(item.ciclo) === identificadorCiclo &&
            item.variable === variable
        );

        if (!yaRegistrada) {
            historial.push({
                ciclo: datos.ciclo,
                variable: variable,
                zscore: z,
                actual: Number.isFinite(actual) ? actual : null
            });
        }
    } else {
        contadores[variable] = 0;
    }

    if (contadores[variable] >= LIMITE_FALLA) {
        estado = "FALLA";
        falla = true;
    } else if (esAnomalia) {
        estado = "ANOMALIA";
    } else {
        estado = "NORMAL";
    }

    estados[variable] = {
        actual: Number.isFinite(actual) ? actual : null,
        zscore: z,
        estado: estado,
        contador: contadores[variable]
    };

    texto += variable.toUpperCase() + ": " +
        (Number.isFinite(actual) ? actual : "N/A") +
        " | Z: " + z.toFixed(2) +
        " | " + estado;

    if (esAnomalia) {
        texto += " | CONSECUTIVAS: " +
            contadores[variable];
    }

    texto += "\n";
}

// ==========================================
// 7. LIMITAR EL HISTORIAL
// ==========================================
if (historial.length > MAX_HISTORIAL) {
    historial = historial.slice(-MAX_HISTORIAL);
}

// ==========================================
// 8. DETERMINAR ESTADO GENERAL
// ==========================================
let estadoGeneral;

if (falla) {
    estadoGeneral = "FALLA";
} else if (anomalia) {
    estadoGeneral = "ANOMALIA DETECTADA";
} else if (evaluadas === 0) {
    estadoGeneral = "EN EVALUACION";
} else {
    estadoGeneral = "CICLO NORMAL";
}

// ==========================================
// 9. GUARDAR INFORMACIÓN ACTUALIZADA
// ==========================================
flow.set("contadorAnomalias", contadores);
flow.set("historialAnomalias", historial);

flow.set("estadoAnomaliaDashboard", {
    ciclo: datos.ciclo,
    estadoGeneral: estadoGeneral,
    anomalia: anomalia,
    falla: falla,
    estados: estados
});

flow.set(
    "ultimoCicloEvaluadoDeteccion",
    identificadorCiclo
);

// ==========================================
// 10. ENVIAR RESULTADO
// ==========================================
texto += "-------------------------\n";
texto += "ESTADO: " + estadoGeneral;

msg.payload = texto;
return msg;

