            CN: zscore.CN,
            caudal: zscore.caudal || null
        }
        : null,

    estado: estado
        ? {
            ciclo: estado.ciclo,
            estadoGeneral: estadoGeneral,
            anomalia: estado.anomalia,
            falla: estado.falla || false,
            estados: estado.estados
        }
        : {
