flow.set("sumaCaudal", 0);
flow.set("sumaPresion", 0);
flow.set("sumaTiempo", 0);

// 3. Reiniciar contadores de anomalías consecutivas
flow.set("contadorAnomalias", {
    AP: 0,
    AN: 0,
    BP: 0,
    BN: 0,
    CP: 0,
    CN: 0,
    caudal: 0
});

// 4. Limpiar estado general de anomalías
